function round(points){
 let p=points;
 for(let pass=0;pass<3;pass++){
  const next=[];for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length];next.push([.75*a[0]+.25*b[0],.75*a[1]+.25*b[1]],[.25*a[0]+.75*b[0],.25*a[1]+.75*b[1]]);}p=next;
 }return p;
}
export const GAME_SHAPES=Object.fromEntries(Object.entries(CONTROL).map(([id,p])=>[id,round(p)]));

